edges = [(1,16), (5,15), (4,13), (2,7), (6,13), (8,9), (2,6), (8,15), (5,6), (7,15), (2,5), (3,12), (1,11), (9,14), (4,7), (12,16), (4,16), (1,9), (7,11), (6,11), (13,14), (3,16), (10,12), (12,13), (0,12), (1,3), (0,14)]

print("Number of edges:", len(edges))
print("All unique?", len(edges) == len(set(edges)))
print("All u < v?", all(u < v for u, v in edges))
print("Max vertex:", max(max(u, v) for u, v in edges))
print("Min vertex:", min(min(u, v) for u, v in edges))

# Check for triangles just for fun
from itertools import combinations
adj = {i: set() for i in range(17)}
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

triangles = []
for u in range(17):
    for v in adj[u]:
        if v > u:
            for w in adj[v]:
                if w > v and w in adj[u]:
                    triangles.append((u, v, w))
print("Triangles found:", triangles)
